// The run viewers: for each experiment, the exact prompt, reply, bytes and test results of every run. Their data is in
// assets/runs, generated by scripts/make_runs.py. Large files load only when asked for. Nothing here runs a binary:
// bytes are only ever shown as hex.
(() => {
  const BASE = "assets/runs/";
  const LOAD_FAILED = location.protocol === "file:"
    ? "Browsers block loading this from a file:// page. Preview the post with python3 -m http.server."
    : "This didn't load. Try reloading the page.";
  const cache = new Map();

  const load = (path, as) => {
    const key = `${as}:${path}`;
    if (!cache.has(key)) {
      cache.set(key, fetch(BASE + path).then((r) => {
        if (!r.ok) throw new Error(`${r.status}`);
        return r[as]();
      }));
    }
    return cache.get(key);
  };

  const el = (tag, props = {}, ...children) => {
    const node = Object.assign(document.createElement(tag), props);
    node.append(...children.filter((c) => c !== null && c !== undefined));
    return node;
  };

  const fmt = (n) => n.toLocaleString("en-US");

  const pre = (extra = "") => el("pre", { className: `rv-pre ${extra}`.trim(), tabIndex: 0 });

  const fill = (target, path, as, render) => {
    target.textContent = "Loading…";
    return load(path, as).then(render).catch(() => {
      target.textContent = LOAD_FAILED;
    });
  };

  // ---- Hex, in the same format as the prompts' dumps. Bytes that differ from `base` are marked. ----
  const hexDump = (bytes, base) => {
    const lines = [];
    for (let off = 0; off < bytes.length; off += 16) {
      const cells = [];
      for (let i = off; i < Math.min(off + 16, bytes.length); i++) {
        const cell = bytes[i].toString(16).padStart(2, "0");
        cells.push(base && base[i] !== bytes[i] ? `<mark>${cell}</mark>` : cell);
      }
      lines.push(`${off.toString(16).padStart(8, "0")}: ${cells.join(" ")}`);
    }
    return lines.join("\n");
  };

  // ---- A row: label, a short description, actions, then the content. A row with content can be folded away. ----
  // `folded` starts it closed; `onOpen` runs the first time it is opened.
  const row = (label, desc, actions, content, { folded = false, onOpen } = {}) => {
    const labelNode = el("span", { className: "io-label", textContent: label });
    const node = el("div", { className: "rv-row" });
    let head = labelNode;
    if (content) {
      let opened = false;
      const sync = () => {
        const isFolded = node.classList.contains("rv-folded");
        head.setAttribute("aria-expanded", String(!isFolded));
        if (!isFolded && !opened) {
          opened = true;
          if (onOpen) onOpen();
        }
      };
      head = el("button", { type: "button", className: "rv-fold" },
        el("span", { className: "rv-chevron", ariaHidden: "true" }), labelNode);
      head.title = `Hide or show ${label.toLowerCase()}`;
      head.addEventListener("click", () => {
        node.classList.toggle("rv-folded");
        sync();
      });
      node.classList.toggle("rv-folded", folded);
      queueMicrotask(sync);
    }
    node.append(
      el("div", { className: "rv-head" },
        head,
        el("span", { className: "rv-desc" }, ...[].concat(desc)),
        el("span", { className: "rv-actions" }, ...actions)),
      ...(content ? [content] : []));
    return node;
  };

  // Buttons that switch one row between views. The first view is shown at once.
  const views = (options, target) => {
    const buttons = options.map(([text, show]) => {
      const button = el("button", { type: "button", textContent: text });
      button.addEventListener("click", () => {
        buttons.forEach((b) => b.setAttribute("aria-pressed", String(b === button)));
        show(target);
      });
      return button;
    });
    buttons.forEach((b, i) => b.setAttribute("aria-pressed", String(i === 0)));
    options[0][1](target);
    return options.length > 1 ? el("span", { className: "rv-views" }, ...buttons) : null;
  };

  const showText = (path) => (target) => {
    const box = pre("rv-wrap");
    target.replaceChildren(box);
    fill(box, path, "text", (text) => { box.textContent = text; });
  };

  // ---- Input ----
  const inputRow = (run) => {
    const box = pre();
    const dumpNote = run.hexRows ? ` + a hex dump of ${fmt(run.inputBytes || 0)} bytes` : "";
    const preview = () => {
      box.textContent = run.promptHead;
      if (run.hexRows) box.textContent += `[${fmt(run.hexRows)} rows of hex. Show the full prompt to read them.]`;
    };
    preview();

    const actions = [];
    if (run.hexRows) {
      const toggle = el("button", { type: "button", textContent: "Show full prompt" });
      let open = false;
      toggle.addEventListener("click", () => {
        open = !open;
        toggle.textContent = open ? "Hide the hex dump" : "Show full prompt";
        if (open) {
          fill(box, `${run.dir}/${run.files.prompt}`, "text", (text) => { box.textContent = text; });
        } else {
          preview();
        }
        box.classList.toggle("rv-tall", open);
      });
      actions.push(toggle);
    }

    const desc = run.hexWithheld
      ? `The exact prompt, without the ${fmt(run.inputBytes)}-byte sample's hex dump`
      : `The exact prompt${dumpNote}`;
    return row("Input", desc, actions, box, { folded: true });
  };

  // ---- Output ----
  const outputRow = (run, folded) => {
    const target = el("div");
    showText(`${run.dir}/${run.files.reply}`)(target);
    const desc = run.hexWithheld ? "The model's reply, with the server address masked" : "The model's reply, unedited";
    return row("Output", desc, [], target, { folded });
  };

  // ---- Bytes the model produced ----
  const editsTable = (run) => (target) => {
    const box = el("div", { className: "rv-scroll", tabIndex: 0 });
    target.replaceChildren(box);
    fill(box, `${run.dir}/${run.files.patch}`, "json", (patch) => {
      const body = el("tbody");
      patch.edits.forEach((edit) => {
        body.append(el("tr", {},
          el("td", { textContent: edit.offset }),
          el("td", { className: "rv-old", textContent: edit.old }),
          el("td", { className: "rv-new", textContent: edit.new })));
      });
      box.replaceChildren(el("table", { className: "rv-table rv-edits" },
        el("thead", {}, el("tr", {},
          el("th", { textContent: "Offset" }),
          el("th", { textContent: "Original bytes" }),
          el("th", { textContent: "Sol 6.1's bytes" }))),
        body));
    });
  };

  const hexView = (run, file, baseFile) => (target) => {
    const box = pre();
    target.replaceChildren(box);
    box.textContent = "Loading…";
    Promise.all([
      load(`${run.dir}/${file}`, "arrayBuffer"),
      baseFile ? load(`${run.dir}/${baseFile}`, "arrayBuffer") : null,
    ]).then(([bytes, base]) => {
      // Only hex digits, offsets and <mark> reach innerHTML here.
      box.innerHTML = hexDump(new Uint8Array(bytes), base && new Uint8Array(base));
    }).catch(() => {
      box.textContent = LOAD_FAILED;
    });
  };

  const bytesRow = (run) => {
    const target = el("div");
    if (run.bytes.kind === "patch") {
      const switcher = views([
        ["Edits", editsTable(run)],
        ["Patched file", hexView(run, run.files.patched, run.files.original)],
      ], target);
      const desc = `${fmt(run.bytes.changed)} of ${fmt(run.bytes.size)} bytes changed, in ${run.bytes.edits} edits`;
      return row("Bytes", desc, [switcher], target);
    }
    hexView(run, run.files.program)(target);
    return row("Bytes", `The complete ${fmt(run.bytes.size)}-byte file Sol 6.1 wrote`, [], target);
  };

  // ---- Test results ----
  const shorten = (value) => {
    const text = JSON.stringify(value);
    return text.length > 90 ? `${text.slice(0, 90)}… (${fmt(text.length)} characters)` : text;
  };

  const testsRow = (run) => {
    const { passed, total, byTag } = run.tests;
    const tags = Object.entries(byTag).map(([tag, [p, t]]) => `${tag} ${p}/${t}`).join(", ");
    const target = el("div");
    const showCases = () => {
      const box = el("div", { className: "rv-scroll", tabIndex: 0 });
      target.replaceChildren(box);
      fill(box, `${run.dir}/${run.files.tests}`, "json", (report) => {
        const body = el("tbody");
        report.results.forEach((test) => {
          const same = test.expected.stdout === test.got.stdout && test.expected.exit === test.got.exit;
          body.append(el("tr", {},
            el("td", { textContent: test.name }),
            el("td", { textContent: test.tags.join(", ") }),
            el("td", { className: test.pass ? "rv-pass" : "rv-fail", textContent: test.pass ? "pass" : "FAIL" }),
            el("td", { textContent: same ? shorten(test.got.stdout) : `${shorten(test.expected.stdout)} / ${shorten(test.got.stdout)}` }),
            el("td", { textContent: String(test.got.exit) })));
        });
        box.replaceChildren(el("table", { className: "rv-table rv-cases" },
          el("thead", {}, el("tr", {}, ...["Case", "Tags", "Result", "stdout (same as the reference)", "Exit"]
            .map((h) => el("th", { textContent: h })))),
          body));
      });
    };
    // The cases stay folded, and load only when the arrow opens them.
    return row("Tests", `${passed}/${total} matched the reference build (${tags})`,
      [], target, { folded: true, onOpen: showCases });
  };

  // ---- The run's record ----
  const recordRow = (run) => row("Run", [
    el("code", { textContent: run.model }),
    `, effort ${run.effort}: ${fmt(run.usage.input)} input tokens, ${fmt(run.usage.output)} output, `,
    `${fmt(run.usage.reasoning)} reasoning, ${fmt(run.seconds)} s${run.audit ? `. ${run.audit}` : ""}.`,
  ], [], null);

  // ---- One viewer ----
  const showRun = (root, data, index) => {
    const run = data.runs[index];
    const body = root.querySelector(".rv-body");
    body.replaceChildren(...[
      inputRow(run),
      outputRow(run, ["exp2", "exp3"].includes(root.dataset.exp)),
      run.bytes ? bytesRow(run) : null,
      run.tests ? testsRow(run) : null,
      recordRow(run),
      run.note ? el("p", { className: "rv-note", textContent: run.note }) : null,
    ].filter(Boolean));
    root.querySelectorAll("[role=tab]").forEach((tab, i) => {
      tab.setAttribute("aria-selected", String(i === index));
      tab.tabIndex = i === index ? 0 : -1;
    });
  };

  const mount = (root) => {
    const data = window.RUNS && window.RUNS[root.dataset.exp];
    if (!data) return;
    root.classList.add("rv");
    const tabs = data.runs.length > 1 ? el("div", { className: "demo-tabs rv-tabs", role: "tablist" }) : null;
    if (tabs) {
      tabs.setAttribute("aria-label", "Run");
      data.runs.forEach((run, i) => {
        const tab = el("button", { type: "button", textContent: run.label });
        tab.setAttribute("role", "tab");
        tab.addEventListener("click", () => showRun(root, data, i));
        tab.addEventListener("keydown", (event) => {
          const step = { ArrowRight: 1, ArrowLeft: -1 }[event.key];
          if (!step) return;
          event.preventDefault();
          const next = (i + step + data.runs.length) % data.runs.length;
          showRun(root, data, next);
          tabs.children[next].focus();
        });
        tabs.append(tab);
      });
    }
    root.replaceChildren(...[tabs, el("div", { className: "rv-body" })].filter(Boolean));
    showRun(root, data, 0);
  };

  // The Distill template re-renders the article after load, so mount whatever is still empty after that.
  window.addEventListener("load", () => {
    const start = () => document.querySelectorAll("[data-exp]:empty").forEach(mount);
    start();
    setTimeout(start, 300);
    setTimeout(start, 1200);
  });
})();
